def sha(b):return hashlib.sha256(b).hexdigest()
def diff(a,b,old,new):
    return b''.join(difflib.diff_bytes(difflib.unified_diff,a.splitlines(True),b.splitlines(True),fromfile=old.encode(),tofile=new.encode(),n=3))
def verify(root):
    root=root.resolve();reads={}
    def read(name):
        p=PurePosixPath(name)
        need(not p.is_absolute() and '..' not in p.parts,'Unsafe declared input')
        path=root.joinpath(*p.parts)
        need(path.is_file() and not path.is_symlink() and path.resolve().is_relative_to(root),'Declared input missing or outside repository')
        if name not in reads:reads[name]=path.read_bytes()
        return reads[name]
    def pinned(name,digest,message):
        b=read(PACKET+'/'+name);need(sha(b)==digest,message);return json.loads(b)
    evidence=pinned('EVIDENCE_MAP.json',MAP_SHA,'Archive map changed');contents={};origins={}
    for obj in evidence['objects']:
        need(obj['sha256'] not in contents,'Duplicate archive object');z=read(PACKET+'/'+obj['path'])
        need(sha(z)==obj['stored_sha256'] and len(z)==obj['stored_bytes'],'Compressed archive changed')
        b=gzip.decompress(z)
        need(sha(b)==obj['sha256'] and len(b)==obj['bytes'] and len(b.splitlines())==obj['lines'],'Archived source changed')
        contents[obj['sha256']]=b
        for origin in obj['origins']:
            need(origin['path'] not in origins,'Duplicate original alias');origins[origin['path']]=obj['sha256']
    def archived(name):return contents[origins[name]]
    contract=evidence['accepted_source_package'];prefix=contract['path']+'/'
    def source(name):return archived(prefix+name)
    need(contract['freeze_sha256']==SOURCE_FREEZE_SHA and sha(source('FINAL_FREEZE.json'))==SOURCE_FREEZE_SHA,'Accepted source freeze differs')
    seal=json.loads(source('FINAL_FREEZE.json'));members=contract['members'];extras=contract['additional_files']
    need(seal['files']==members and len(members)==contract['member_count']==47,'Assembly membership differs')
    need(len(extras)==1 and extras[0]['path']=='FINAL_FREEZE.json' and contract['complete_file_count']==48,'Assembly additional membership differs')
    need({p for p in origins if p.startswith(prefix)}=={prefix+r['path'] for r in members+extras},'Complete assembly aliases differ')
    for r in members+extras:
        b=source(r['path']);need(sha(b)==r['sha256'] and len(b)==r['bytes'],'Assembly member identity differs')
    selection=json.loads(source('EVIDENCE_MANIFEST.json'))['files']
    need(len(selection)==evidence['original_source_selection_count']==24,'Original source selection differs')
    for r in selection:
        b=source(r['archive_path'])
        need(b==archived(r['original_path']) and sha(b)==r['sha256'] and len(b)==r['bytes'],'Original source alias differs')
    mapping=json.loads(source('SOURCE_MAP.json'));accepted=source(mapping['candidate']);wrapper=source(mapping['wrapper'])
    extraction=mapping['complete_extractions'];need(len(extraction)==1,'Accepted extraction count differs');x=extraction[0];core=source(x['source_archive'])
    need(sha(core)==x['source_sha256']==CORE_HASHES[0] and len(core)==x['bytes'] and len(core.splitlines())==x['lines']==248
         and accepted.count(core)==x['occurrences']==1 and accepted[x['start_byte']:x['exclusive_end_byte']]==core,'Complete original proof differs')
    need(sha(accepted)==mapping['candidate_sha256'] and sha(wrapper)==mapping['wrapper_sha256']
         and accepted==wrapper+b'\n'+core+mapping['footer_utf8'].encode(),'Accepted candidate reconstruction differs')
    need(accepted[:x['start_byte']].count(b'\n')+1==x['first_line'] and accepted[:x['exclusive_end_byte']].count(b'\n')==x['last_line'],'Accepted extraction lines differ')
    edits=pinned('PUBLICATION_EDITS.json',EDITS_SHA,'Publication transformation changed')
    need(edits['source_freeze_sha256']==SOURCE_FREEZE_SHA and edits['additional_mathematical_body_edits']==[] and len(edits['notes'])==1
         and edits['accepted_wrapper_edit_scope']=='parent links and publication/source status only; full original/current diff','Publication scope differs')
    note=edits['notes'][0];assembled=b'';published_cores=[];rendered_wrapper=None;framing=[]
    need(archived(note['accepted_candidate_path'])==accepted and sha(accepted)==note['accepted_candidate_sha256'],'Accepted publication candidate differs')
    need([r['kind'] for r in note['pieces']]==['rendered_wrapper','literal_framing','accepted_core_slice','literal_framing'],'Publication piece order differs')
    for r in note['pieces']:
        if r['kind']=='rendered_wrapper':
            b=archived(r['source_path']);need(b==wrapper and sha(b)==r['source_sha256'],'Accepted wrapper differs')
            for t in r['replacements']:
                old,new=t['original'].encode(),t['rendered'].encode()
                need(t['scope']=='parent link or source/publication status only' and b.count(old)==1,'Wrapper replacement differs');b=b.replace(old,new,1)
            rendered_wrapper=b
        elif r['kind']=='accepted_core_slice':
            b=archived(r['source_path'])
            need(b==core and sha(b)==r['source_sha256']==r['expected_slice_sha256'] and r['source_line_start']==1
                 and r['source_line_end']==248 and r['additional_mathematical_body_edits']==[],'Complete published proof differs');published_cores.append(b)
        else:b=r['text'].encode();framing.append(b)
        need(sha(b)==r['sha256'] and len(b)==r['bytes'] and r['byte_offset']==len(assembled),'Publication piece bytes differ')
        need(r['first_line']==assembled.count(b'\n')+1 and r['last_line']==(assembled+b).count(b'\n'),'Publication piece lines differ');assembled+=b
    need(published_cores==[core] and framing==[b'\n',mapping['footer_utf8'].encode()],'Complete body or framing changed')
    actual=read(note['note'])
    need(actual==assembled and sha(actual)==note['published_sha256'] and len(actual)==note['published_bytes']
         and len(actual.splitlines())==note['published_lines'],'Published source does not reconstruct')
    def diff_bytes(r):
        z=read(PACKET+'/'+r['diff']);d=gzip.decompress(z)
        need(sha(z)==r['diff_stored_sha256'] and sha(d)==r['diff_sha256'] and len(d)==r['diff_bytes']
             and len(z)==r['stored_bytes'] and r['context_lines']==3,'Raw diff archive changed');return d
    need(diff_bytes(note)==diff(accepted,actual,note['fromfile'],note['tofile']),'Full publication diff differs')
    wd=edits['wrapper_diff'];need(diff_bytes(wd)==diff(wrapper,rendered_wrapper,wd['fromfile'],wd['tofile']),'Complete wrapper diff differs')
    bindings=pinned('PARENT_BINDINGS.json',PARENTS_SHA,'Parent bindings changed')
    need(bindings['binding_complete'] is True and bindings['direct_edges_verified'] is True and bindings['markdown_citations_verified'] is True
         and bindings['publication_ancestry_is_not_mathematical_dependency'] is True,'Actual published parent binding remains unresolved')
    parents=bindings['parents'];roles=bindings['required_roles'];maps=bindings['canonical_core_maps'];citations=bindings['markdown_citations']
    need(len(parents)==len(roles)==len(maps)==len(citations)==2 and [p['key'] for p in parents]==['interacting_controller','fixed_history'],'Direct parent membership differs')
    expected_sources=['3c02940e2d4f3eb519f459dd658950df77662c7bd431500e52f2509658ed94fe','7fe0df39ecad4aafbbbbfeeae83d2e2372f6527afbaf04223d9ab43dd5ac99b1']
    link_re=re.compile(r'\[[^\]]*\]\(([^)\s#]+\.md)(?:#[^)]*)?\)');text=actual.decode()
    for p,r,x,c,h in zip(parents,roles,maps,citations,expected_sources):
        b=read(p['path']);s=archived(x['source_path']);path=PurePosixPath(p['path'])
        need(sha(b)==p['published_sha256']==x['canonical_sha256']==r['canonical_sha256'] and len(b)==p['bytes']==x['canonical_bytes']
             and archived(p['archive_alias'])==b,'Canonical parent bytes changed')
        need(p['key']==r['key']==x['key'] and p['path']==r['canonical_path']==x['canonical_path'] and p['claim_id']==r['actual_claim_id']
             and r['complete_body_identity_verified'] is True and r['relied_role_checked'] is True,'Direct parent role differs')
        start,end=x['byte_start_inclusive'],x['byte_end_exclusive']
        need(x['complete_direct_body'] is True and x['body_edits']==[] and sha(s)==x['source_sha256']==h and len(s)==x['source_bytes']
             and len(s.splitlines())==x['source_lines'] and b.count(s)==x['occurrences']==1 and b[start:end]==s
             and b[:start].count(b'\n')+1==x['first_line'] and b[:end].count(b'\n')==x['last_line'],'Complete parent direct-body extraction differs')
        need(path.parts==('docs',path.name) and path.suffix=='.md' and p['claim_id']==path.stem.lower(),'Unreviewed canonical parent path class')
        literal='['+c['label']+']('+path.name+')'
        need(c['parent_path']==p['path'] and c['claim_id']==p['claim_id'] and c['target']==path.name and c['markdown']==literal
             and text.count(literal)==1 and c['label'].strip()==c['label'] and not any(t in c['label'] for t in '[]\n\r'),'Parent Markdown citation differs')
    need(link_re.findall(text)==[c['target'] for c in citations],'Recognized Markdown citations differ from declared parents')
    graph=pinned('CLAIM_REGISTRY_ADDITIONS.json',GRAPH_SHA,'Graph proposal changed');deps=[p['claim_id'] for p in parents]
    need(graph['binding_complete'] is True and len(graph['nodes'])==1 and graph['nodes'][0]['claim_id']==CLAIM and graph['nodes'][0]['path']==note['note']
         and graph['nodes'][0]['runner']=='scripts/interacting_controller_history_application_identity_2026_10_14.py' and graph['nodes'][0]['deps']==deps
         and graph['direct_edges']==[{'from':CLAIM,'to':d} for d in deps] and graph['new_roots']==[]
         and graph['expected_delta']=={'nodes':1,'edges':2,'roots':0},'Direct graph proposal differs')
    status=pinned('SOURCE_REVIEW_STATUS.json',STATUS_SHA,'Review scope changed')
    acceptance=read(PACKET+'/INTERACTING_HISTORY_ASSEMBLY_ROOT_ACCEPTANCE.json');review=read(PACKET+'/INTERACTING_HISTORY_ASSEMBLY_ROOT_REVIEW.md');scope=json.loads(acceptance)
    need(sha(acceptance)==status['source_assembly_root_acceptance_sha256'] and sha(review)==status['source_assembly_root_review_sha256'],'Assembly root review changed')
    need(scope==status['source_review_coverage_verbatim'] and scope['assembly_freeze_sha256']==SOURCE_FREEZE_SHA and scope['root_review_sha256']==sha(review)
         and scope['canonical_execution_authorized'] is False and scope['disposition']=='accepted_for_source_only_publication_preparation_with_pending_actual_IC_parent_binding'
         and scope['accepted_core_sha256']==CORE_HASHES[0] and scope['expected_external_scientific_roles']==['interacting_controller','fixed_history'],'Assembly acceptance scope differs')
    need(status['no_go_packet_pass'] is False and status['new_independent_mathematical_review'] is False and status['unchanged_complete_core_coverage_reused'] is True
         and status['mathematical_core_edits']==0 and status['publication_runtime_executed_by_source_preparer'] is False
         and status['accepted_wrapper_edit_scope']==edits['accepted_wrapper_edit_scope'],'Review limitation differs')
    need(all(status[k] is True for k in ['fixed_finite_protocol_only','full_unnormalized_CQ_reference_output','original_physical_chain_identification',
         'supplied_computable_U_and_circuit_to_history_certificate','pulled_back_positive_Fock_weight','broad_precision_class_not_replaced_by_narrow_supplement',
         'actual_pointer_work_and_imperfect_completion_energy_retained','mathematical_record_pinching_distinct_from_physical_apparatus',
         'preparation_sufficiency_not_necessity','scalar_clock_padding_distinct_from_idle_steps'])
         and all(status[k] is False for k in ['native_realization_proved','physical_measurement_apparatus_supplied','kinetic_joint_limit_proved',
         'normalized_rare_branch_control','retained_audit_status']),'Mandatory export scope changed')
    for name,p in EXTRA_PINS.items():
        b=read(name);need(sha(b)==p['sha256'] and len(b)==p['bytes'],'Additional publication integrity input changed')
    need(set(reads)==set(AUDIT_INPUT_PATHS) and len(AUDIT_INPUT_PATHS)==len(set(AUDIT_INPUT_PATHS)),'Declared read closure differs')
    return {'result':'source_identities_and_reconstruction_match','claim_id':CLAIM,'meaning':'Byte integrity only; no mathematical calculation, proof or audit executed.',
        'mathematical_operations_executed':False,'mathematical_predicates_executed':0,'scientific_mutations_executed':0,
        'no_go_packet_pass_supplied_by_tool':False,'independent_review_supplied_by_tool':False,
        'external_scientific_input_reads':[p['path'] for p in parents],'package_local_integrity_reads':sorted(set(reads)-{p['path'] for p in parents})}
def main():
    print(json.dumps(verify(Path(__file__).resolve().parents[1]),sort_keys=True))
    print('per_element: checked and not executed — source integrity only; no circuit or channel error bound was evaluated.')
    print('per_site: checked and not executed — source integrity only; physical chain and supplied apparatus resources remain premises.')
    print('per_mode: checked and not executed — source integrity only; no Fock-weight or finite-volume estimate was calculated.')
    print('per_block: checked and not executed — source integrity only; no full-Hamiltonian dephasing or covariance calculation ran.')
    print('lattice_wide: checked and not executed — source integrity only; no native apparatus, kinetic limit or retained theorem was verified.')
if __name__=='__main__':
    try:main()
    except Exception as error:
        print(json.dumps({'result':'identity_verification_incomplete','error':str(error),'mathematical_operations_executed':False,
            'mathematical_predicates_executed':0,'scientific_mutations_executed':0}),file=sys.stderr)
        raise SystemExit(1)
